async fn send_to_addr(state: &Arc<PreviewAppState>, addr: SocketAddr, message: Message) {
    let clients = state.clients.lock().await;
    if let Some(entry) = clients.get(&addr) {
        let _ = entry.tx.send(message);
    }
}

async fn broadcast_to_legacy(state: &Arc<PreviewAppState>, message: Message) {
    let clients = state.clients.lock().await;
    for entry in clients.values() {
        if entry.kind == ConnectionKind::Legacy {
            let _ = entry.tx.send(message.clone());
        }
    }
}

async fn forward_host_message_to_editor(state: &Arc<PreviewAppState>, message: String) {
    let channel = state.editor_event_channel.read().await.clone();
    if let Some(channel) = channel {
        let _ = channel.send(message);
    }
}

// -------- V1 消息处理 --------

async fn handle_register_preview_request(
    state: &Arc<PreviewAppState>,
    addr: SocketAddr,
    request_id: String,
    payload: RegisterPreviewRequestPayload,
) {
    let accepted = {
        let mut registry = state.preview_registry.lock().await;
        registry.register(addr, payload)
    };

    if !accepted {
        let _ = send_to_addr(state, addr, Message::Close(None)).await;
        return;
    }

    match build_empty_response(SESSION_REGISTER_PREVIEW_TYPE, &request_id) {
        Ok(response) => {
            let _ = send_to_addr(state, addr, Message::Text(response.into())).await;
        }
        Err(_) => {
            let _ = send_to_addr(state, addr, Message::Close(None)).await;
        }
    }
}

async fn handle_v1_socket_message(state: &Arc<PreviewAppState>, addr: SocketAddr, text: String) {
    if let Some((request_id, payload)) = parse_register_preview_request(&text) {
        handle_register_preview_request(state, addr, request_id, payload).await;
        return;
    }

    if !is_host_message(&text) {
        return;
    }

    let should_forward = {
        let registry = state.preview_registry.lock().await;
        registry.preferred_event_source() == Some(addr)
    };

    if should_forward {
        forward_host_message_to_editor(state, text).await;
    }
}

// -------- Legacy 消息处理 --------

async fn handle_legacy_socket_message(
    state: &Arc<PreviewAppState>,
    addr: SocketAddr,
    text: String,
) {
    let Some(message) = parse_legacy_message(&text) else {
        return;
    };

    if message.command == LEGACY_COMMAND_SYNC_FORWARD {
        let is_new = {
            let mut ready = state.ready_legacy.lock().await;
            ready.insert(addr)
        };
        if is_new {
            if let Ok(event) = build_preview_ready_updated_event(true) {
                forward_host_message_to_editor(state, event).await;
            }
        }
        if let Ok(event) = build_stage_snapshot_updated_event(
            &message.scene,
            message.sentence,
            &message.stage_sync_msg,
        ) {
            forward_host_message_to_editor(state, event).await;
        }
    } else if message.command == LEGACY_COMMAND_FAST_PREVIEW_TIMEOUT {
        if let Ok(payload) = serde_json::from_str::<serde_json::Value>(&message.message) {
            if let Ok(event) = serde_json::to_string(&serde_json::json!({
                "kind": "event",
                "type": "preview.event.fast-preview-timeout",
                "payload": payload,
            })) {
                forward_host_message_to_editor(state, event).await;
            }
        }
    }
}

async fn cleanup_disconnected_preview(state: &Arc<PreviewAppState>, addr: SocketAddr) {
    let removed = state.clients.lock().await.remove(&addr);
    match removed.map(|entry| entry.kind) {
        Some(ConnectionKind::V1) => {
            let changed = state.preview_registry.lock().await.unregister(addr);
            if changed {
                if let Ok(event) = build_preview_ready_updated_event(false) {
                    forward_host_message_to_editor(state, event).await;
                }
            }
        }
        Some(ConnectionKind::Legacy) => {
            state.ready_legacy.lock().await.remove(&addr);
        }
        None => {}
    }
}

// -------- WebSocket 网关 --------

async fn handle_ws(
    ws: WebSocketUpgrade,
    headers: HeaderMap,
    AxumState(state): AxumState<Arc<PreviewAppState>>,
    ConnectInfo(addr): ConnectInfo<SocketAddr>,
) -> impl IntoResponse {
    let requested_subprotocol = headers
        .get(SEC_WEBSOCKET_PROTOCOL)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty());

    // V1 引擎: 带指定子协议
    if requests_v1_subprotocol(requested_subprotocol) {
        return ws
            .protocols([EDITOR_PREVIEW_PROTOCOL_V1_SUBPROTOCOL])
            .on_upgrade(move |socket| handle_ws_socket(socket, state, addr, ConnectionKind::V1))
            .into_response();
    }

    // Legacy 引擎: 无子协议
    if requested_subprotocol.is_none() {
        return ws
            .on_upgrade(move |socket| handle_ws_socket(socket, state, addr, ConnectionKind::Legacy))
            .into_response();
    }

    // 其他未知子协议一律拒绝
    StatusCode::BAD_REQUEST.into_response()
}

async fn handle_ws_socket(
    socket: WebSocket,
    state: Arc<PreviewAppState>,
    addr: SocketAddr,
    kind: ConnectionKind,
) {
    let (mut ws_tx, mut ws_rx) = socket.split();
    let (unicast_tx, mut unicast_rx) = mpsc::unbounded_channel();
    state.clients.lock().await.insert(
        addr,
        ClientEntry {
            kind,
            tx: unicast_tx,
        },
    );

    let mut recv_task = tokio::spawn({
        let state = state.clone();
        async move {
            while let Some(Ok(message)) = ws_rx.next().await {
                match message {
                    Message::Text(text) => match kind {
                        ConnectionKind::V1 => {
                            handle_v1_socket_message(&state, addr, text.to_string()).await
                        }
                        ConnectionKind::Legacy => {
                            handle_legacy_socket_message(&state, addr, text.to_string()).await;
                        }
                    },
                    Message::Close(_) => break,
                    _ => continue,
                }
            }
        }
    });

    let mut send_task = tokio::spawn(async move {
        while let Some(message) = unicast_rx.recv().await {
            if ws_tx.send(message).await.is_err() {
                break;
            }
        }
    });

    tokio::select! {
        _ = &mut recv_task => {
            send_task.abort();
            let _ = send_task.await;
        },
        _ = &mut send_task => {
            recv_task.abort();
            let _ = recv_task.await;
        },
    }

    cleanup_disconnected_preview(&state, addr).await;
}

// -------- 静态文件服务 --------

/// 清理并校验逻辑请求路径, 拒绝路径穿越。
fn sanitize_request_path(raw: &str) -> Option<PathBuf> {
    let decoded = percent_decode_str(raw).decode_utf8().ok()?;
    let mut result = PathBuf::new();
    for component in Path::new(decoded.as_ref()).components() {
        match component {
            Component::Normal(name) => result.push(name),
            Component::CurDir => {}
            _ => return None, // ParentDir / RootDir / Prefix 一律拒绝
        }
    }
    Some(result)
}

/// 按 overlay 语义解析逻辑路径: 上层(项目)优先, 下层(引擎)兜底。
async fn resolve_file(project: &Path, engine: Option<&Path>, logical: &Path) -> Option<PathBuf> {
    let upper = project.join(logical);
    if tokio::fs::try_exists(&upper).await.unwrap_or(false) {
        return Some(upper);
    }
    if let Some(engine) = engine {
        let lower = engine.join(logical);
        if tokio::fs::try_exists(&lower).await.unwrap_or(false) {
            return Some(lower);
        }
    }
    None
}

async fn handle_static_request(
    AxumState(state): AxumState<Arc<PreviewAppState>>,
    AxumPath(hash): AxumPath<String>,
    request_path: Option<String>,
) -> Response {
    let site = {
        let sites = state.sites.read().await;
        sites.get(&hash).cloned()
    };

    let Some(site) = site else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let logical_path = match sanitize_request_path(request_path.as_deref().unwrap_or("index.html"))
    {
        Some(path) => path,
        None => return StatusCode::BAD_REQUEST.into_response(),
    };

    let Some(physical_path) =
        resolve_file(&site.project, site.engine.as_deref(), &logical_path).await
    else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let request = axum::http::Request::builder()
        .uri("/")
        .body(axum::body::Body::empty())
        .expect("空请求构造不会失败");

    ServeFile::new(&physical_path)
        .oneshot(request)
        .await
        .map(IntoResponse::into_response)
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

fn normalize_project_path(path: &str) -> Result<(String, PathBuf), String> {
    let path_buf = PathBuf::from(path);
    if !path_buf.is_dir() {
        return Err("路径必须是目录".into());
    }
    let canonical = path_buf.canonicalize().map_err(|e| e.to_string())?;

    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    canonical.hash(&mut hasher);
    let hash = format!("{:x}", hasher.finish());

    Ok((hash, path_buf))
}

// -------- Tauri 命令 --------

#[tauri::command]
pub async fn start_preview_server(
    state: TauriState<'_, Mutex<PreviewState>>,
    host: String,
    port: u16,
    on_message: Channel<String>,
) -> Result<String, String> {
    let mut state_guard = state.lock().await;

    if let Some(handle) = state_guard.server_handle.take() {
        let _ = handle.shutdown_tx.send(());
        handle.join_handle.await.ok();
    }

    let address = format!("{host}:{port}");
    let listener = match TcpListener::bind(&address).await {
        Ok(listener) => listener,
        Err(_) => TcpListener::bind(format!("{host}:0"))
            .await
            .map_err(|e| e.to_string())?,
    };
    let addr = listener.local_addr().map_err(|e| e.to_string())?;

    *state_guard.app_state.editor_event_channel.write().await = Some(on_message);

    let app = Router::new()
        .route("/api/webgalsync", get(handle_ws))
        .route("/game/{hash}", get(|uri: axum::http::Uri| async move {
            Redirect::permanent(&format!("{}/", uri.path()))
        }))
        .route(
            "/game/{hash}/",
            get(
                |state: AxumState<Arc<PreviewAppState>>, hash: AxumPath<String>| async move {
                    handle_static_request(state, hash, None).await
                },
            ),
        )
        .route(
            "/game/{hash}/{*path}",
            get(
                |state: AxumState<Arc<PreviewAppState>>,
                 path: AxumPath<(String, String)>| async move {
                    let (hash, path) = path.0;
                    handle_static_request(state, AxumPath(hash), Some(path)).await
                },
            ),
        )
        .with_state(state_guard.app_state.clone());

    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let join_handle = tokio::spawn(async move {
        if let Err(e) = axum::serve(
            listener,
            app.into_make_service_with_connect_info::<SocketAddr>(),
        )
        .with_graceful_shutdown(async {
            shutdown_rx.await.ok();
        })
        .await
        {
            eprintln!("预览服务器异常: {e}");
        }
    });

    state_guard.server_handle = Some(ServerHandle {
        join_handle,
        shutdown_tx,
    });

    Ok(format!("http://{addr}"))
}

#[tauri::command]
pub async fn add_static_site(
    state: TauriState<'_, Mutex<PreviewState>>,
    project_path: String,
    engine_path: Option<String>,
) -> Result<String, String> {
    let (hash, project) = normalize_project_path(&project_path)?;
    let engine = match engine_path {
        Some(path) => {
            let path_buf = PathBuf::from(&path);
            if !path_buf.is_dir() {
                return Err("引擎路径必须是目录".into());
            }
            Some(path_buf)
        }
        None => None,
    };

    state
        .lock()
        .await
        .app_state
        .sites
        .write()
        .await
        .insert(hash.clone(), SiteConfig { project, engine });

    Ok(hash)
}

