#[tauri::command]
pub async fn send_preview_command(
    state: TauriState<'_, Mutex<PreviewState>>,
    request: String,
) -> Result<(), String> {
    let app_state = state.lock().await.app_state.clone();

    // V1 目标
    if let Some(target_scope) = target_scope_for_preview_request(&request) {
        let target_addrs = {
            let registry = app_state.preview_registry.lock().await;
            registry.target_addrs_for_request_scope(target_scope)
        };
        for addr in target_addrs {
            let _ = send_to_addr(&app_state, addr, Message::Text(request.clone().into())).await;
        }
    }

    // Legacy 目标 (翻译后广播)
    if let Some(legacy_request) = translate_preview_command_to_legacy(&request) {
        broadcast_to_legacy(&app_state, Message::Text(legacy_request.into())).await;
    }

    Ok(())
}
